

COMMENT ON TABLE revinfo IS 'Revision Information Table for Auditing';
COMMENT ON COLUMN revinfo.rev IS 'Primary key. Revision id references other audit table. [Sensitivity: NONE]';
COMMENT ON COLUMN revinfo.revtstmp IS 'Timestamp of an audit event log. [Sensitivity: NONE]';

COMMENT ON TABLE holds_aud IS 'Audit table for the holds table';

COMMENT ON COLUMN holds_aud.rev IS 'Foreign key. Revision id references revinfo table. [Sensitivity: NONE]';
COMMENT ON COLUMN holds_aud.updated_by IS 'Nullable updated by audit column. [Sensitivity: NONE]';
COMMENT ON COLUMN holds_aud.revtype IS 'Big Int Audit revision type: 0 Insertion, 1 Update, 2 Deletion. [Sensitivity: NONE]';
COMMENT ON COLUMN holds_aud.id IS 'Primary key. A UUIDv7 generated by the application, used as the hold''s permanent public identifier across DPS. [Sensitivity: NONE]';
COMMENT ON COLUMN holds_aud.prison_number IS 'NOMIS offender number (prison number/noms number) of the prisoner that the money has been held from. The link that makes every row here personal data about that prisoner. Updated in place when NOMIS merges two offender records. [Sensitivity: PERSONAL]';
COMMENT ON COLUMN holds_aud.sub_account_ref IS 'The reference used to identify the prisoner sub account of their trust account where the money is being held from - CASH, SPENDS, SAVINGS. [Sensitivity: NONE]';
COMMENT ON COLUMN holds_aud.legacy_hold_number IS 'NOMIS hold number, allowing these records to be linked back to the original source record held in NOMIS. [Sensitivity: NONE]';
COMMENT ON COLUMN holds_aud.hold_location IS 'Prison code, such as MDI, where the money from the prisoner is being held. Read with prison_number it indicates where that prisoner was held at the time. [Sensitivity: PERSONAL]';
COMMENT ON COLUMN holds_aud.hold_from_date IS 'When the money was held from the prisoner. Null if this is not yet released. [Sensitivity: NONE]';
COMMENT ON COLUMN holds_aud.hold_until_date IS 'When the money is expected to be released back to the prisoner. Null if this is open ended. [Sensitivity: NONE]';
COMMENT ON COLUMN holds_aud.hold_type IS 'What kind of hold this is - HOLD or WITHHOLD. [Sensitivity: NONE]';
COMMENT ON COLUMN holds_aud.description IS 'Free text description about the hold. Free text: assume it can name an incident, prisoner, staff member or member of the public, for example when explaining who sent the money that has been held by the prison or the incident that resulted in the money being held. [Sensitivity: OFFICIAL-SENSITIVE]';
COMMENT ON COLUMN holds_aud.amount IS 'The amount of money that is/was held from the prisoner. [Sensitivity: OFFICIAL-SENSITIVE]';
COMMENT ON COLUMN holds_aud.created_at IS 'When this hold record was first created. [Sensitivity: NONE]';
COMMENT ON COLUMN holds_aud.created_by IS 'DPS username of the person who recorded the hold by the prison. [Sensitivity: STAFF]';
COMMENT ON COLUMN holds_aud.HOLD_TRANSACTION_ID IS 'The unique identifier of the prisoner finance general ledger transaction that took the money from the prisoner, allowing these records to be linked back to the financial records held within the general ledger of accounts. [Sensitivity: NONE]';
COMMENT ON COLUMN holds_aud.is_released IS 'A flag indicating whether the money has been released back to the prisoner. [Sensitivity: NONE]';
COMMENT ON COLUMN holds_aud.released_at IS 'When the money was released back to the prisoner. Null if the money has not yet been released. [Sensitivity: NONE]';
COMMENT ON COLUMN holds_aud.RELEASE_TRANSACTION_ID IS 'The unique identifier of the prisoner finance general ledger transaction that returned the money to the prisoner, allowing these records to be linked back to the financial records held within the general ledger of accounts. [Sensitivity: NONE]';


COMMENT ON COLUMN holds.updated_by IS 'Nullable updated by audit column. [Sensitivity: NONE]';
